You are fixing a GitHub issue. Follow the existing code style,
naming conventions, and architecture visible in the files below. Do not
introduce new dependencies or restructure unrelated code.

ISSUE TITLE: Intermittent E2E failure: Share opens a page instead of a dialog
ISSUE DESCRIPTION:
`TestEndToEndUser.test_user_assess` intermittently fails when opening story sharing. The test expects a dialog and attempts to click its **✕** button, but the browser navigates to `/story/sharing?story_id=…`, where that button doesn’t exist.

Running `dev/testpipeline.sh` again on the same branch without changes passed.

A timing issue involving card replacement and HTMX initialization is suspected, but not confirmed.

This excerpt shows the unexpected navigation and missing dialog button:

```text
tests/playwright/test_e2e_user.py:356: in access_story
    page.get_by_role("button", name="✕").click()

E   playwright._impl._errors.TimeoutError: Locator.click: Timeout 5000ms exceeded.
E   Call log:
E     - waiting for get_by_role("button", name="✕")
E       - waiting for navigation to finish...
E       - navigated to "http://localhost:40133/story/sharing?story_id=01a0819c-25a3-76d8-9745-cbc45a304619"
```

Immediately before that, the test opens sharing with:

```python
share_story = story_card().get_by_test_id("share-story")
share_story.dispatch_event("click")
page.get_by_role("button", name="✕").click()
```

ISSUE LABELS: bug


RELEVANT FILES:
--- dev/testpipeline.sh ---
#!/usr/bin/env bash
set -euo pipefail

fail() {
  echo "Error: $*" >&2
  exit 1
}

require_command() {
  command -v "$1" >/dev/null 2>&1 || fail "Missing required command: $1"
}

run_step() {
  printf '\n==> %s\n' "$1"
}

run_in_dir() {
  local dir="$1"
  shift
  (
    cd "$dir"
    "$@"
  )
}

run_models() {
  run_step "src/models"
  run_in_dir src/models uv sync --frozen --all-extras
  run_in_dir src/models uv run --frozen --no-sync ruff check
}

run_core() {
  run_step "src/core"
  run_in_dir src/core uv sync --frozen --all-extras
  run_in_dir src/core uv run --frozen --no-sync ruff check
  run_in_dir src/core uv run --frozen --no-sync pytest
}

run_frontend() {
  run_step "src/frontend"
  run_in_dir src/frontend uv sync --frozen --all-extras
  run_in_dir src/frontend uv run --frozen --no-sync ruff check
  run_in_dir src/frontend uv run --frozen --no-sync djlint --profile=jinja --check frontend/templates
  run_in_dir src/frontend uv run --frozen --no-sync pytest
}

run_frontend_e2e() {
  run_step "src/frontend e2e"
  run_in_dir src/frontend ./build_tailwindcss.sh
  run_in_dir src/frontend uv run --frozen --no-sync pytest --e2e-ci
}

run_worker() {
  run_step "src/worker"
  run_in_dir src/worker uv sync --frozen --all-extras
  run_in_dir src/worker uv run --frozen --no-sync ruff check
  run_in_dir src/worker uv run --frozen --no-sync pytest
}

start_parallel_step() {
  local name="$1"
  local command="$2"
  local log_file="$PARALLEL_LOG_DIR/${name//\//_}.log"

  printf '\n==> %s (started)\n' "$name"
  "$command" >"$log_file" 2>&1 &

  PARALLEL_NAMES+=("$name")
  PARALLEL_PIDS+=("$!")
  PARALLEL_LOGS+=("$log_file")
}

wait_parallel_steps() {
  local failed_steps=()
  local index
  local status

  for index in "${!PARALLEL_PIDS[@]}"; do
    if wait "${PARALLEL_PIDS[$index]}"; then
      printf '\n==> %s (passed)\n' "${PARALLEL_NAMES[$index]}"
    else
      status=$?
      printf '\n==> %s (failed with exit %s)\n' "${PARALLEL_NAMES[$index]}" "$status" >&2
      failed_steps+=("${PARALLEL_NAMES[$index]} (exit $status)")
    fi

    cat "${PARALLEL_LOGS[$index]}"
  done

  if [ "${#failed_steps[@]}" -ne 0 ]; then
    fail "Parallel steps failed: ${failed_steps[*]}."
  fi
}

require_command git
ROOT_DIR="$(git rev-parse --show-toplevel 2>/dev/null)" || fail "Run this command from inside the taranis-ai git worktree."
cd "$ROOT_DIR"

require_command uv

if ! docker compose version >/dev/null 2>&1; then
  fail "Docker Compose is required for frontend e2e tests."
fi

export DEBUG=true

PARALLEL_LOG_DIR="$(mktemp -d)"
trap 'rm -rf "$PARALLEL_LOG_DIR"' EXIT
PARALLEL_NAMES=()
PARALLEL_PIDS=()
PARALLEL_LOGS=()

start_parallel_step "src/models" run_models
start_parallel_step "src/core" run_core
start_parallel_step "src/frontend" run_frontend
start_parallel_step "src/worker" run_worker
wait_parallel_steps

run_frontend_e2e


