        go_to_next_driver_step(page, "Scheduled jobs")
        go_to_next_driver_step(page, "Role")
        go_to_next_driver_step(page, "Role table")
        go_to_next_driver_step(page, "User")
        go_to_next_driver_step(page, "User table")
