        expect(page.locator("#history-tab .stats")).to_have_count(1)
        with_htmx_wait(page, lambda: page.locator('.tab[data-tab="scheduled"]').click())
        with_htmx_wait(page, lambda: page.locator('.tab[data-tab="history"]').click())
        expect(page.locator("#history-tab .stats")).to_have_count(1)

